//! Responses stream staging. Not enabled as a network/auth transport yet.
//! Never releases a function call before the entire response completes.
use std::collections::BTreeMap;
use serde_json::Value;
#[derive(Debug,Default,PartialEq)]pub struct FunctionCall{pub id:String,pub name:String,pub arguments:String,pub done:bool}
#[derive(Debug,Default)]pub struct ResponseStage{pub text:String,pub calls:BTreeMap<String,FunctionCall>,completed:bool,failure:Option<String>,order:Vec<String>,output:Vec<Value>}
impl ResponseStage{
 pub fn push(&mut self,v:&Value)->Result<(),String>{if self.completed||self.failure.is_some(){return Err("Event after terminal response".into())}match v["type"].as_str().unwrap_or(""){
 "response.output_text.delta"=>{self.text.push_str(v["delta"].as_str().unwrap_or(""));},
 "response.output_item.added"=>{let item=&v["item"];if item["type"]=="function_call"{let id=item["id"].as_str().ok_or("Missing function item id")?.to_string();if self.calls.contains_key(&id){return Err("Duplicate function item id".into())}self.order.push(id.clone());self.calls.insert(id,FunctionCall{id:item["call_id"].as_str().unwrap_or("").into(),name:item["name"].as_str().unwrap_or("").into(),arguments:String::new(),done:false});}},
 "response.function_call_arguments.delta"=>{let id=v["item_id"].as_str().ok_or("Missing item id")?;let c=self.calls.get_mut(id).ok_or("Unknown function item")?;if c.done{return Err("Function arguments after done".into())}c.arguments.push_str(v["delta"].as_str().unwrap_or(""));if c.arguments.len()>2*1024*1024{return Err("Function arguments too large".into())}},
 "response.function_call_arguments.done"=>{let id=v["item_id"].as_str().ok_or("Missing item id")?;let c=self.calls.get_mut(id).ok_or("Unknown function item")?;let final_args=v["arguments"].as_str().ok_or("Missing final arguments")?;if !c.arguments.is_empty()&&c.arguments!=final_args{return Err("Function final arguments disagree with deltas".into())}c.arguments=final_args.into();c.done=true;},
 "response.completed"=>{if v["response"]["status"]!="completed"{return Err("Completed event without completed response status".into())}if let Some(output)=v["response"]["output"].as_array(){for item in output{if !matches!(item["type"].as_str(),Some("message"|"reasoning"|"function_call")){return Err("Unsupported Responses output item; cannot preserve continuity".into())}}let final_calls=output.iter().filter(|x|x["type"]=="function_call").collect::<Vec<_>>();if final_calls.len()!=self.calls.len(){return Err("Completed response function set differs from streamed calls".into())}for item in final_calls{let id=item["id"].as_str().ok_or("Final function id missing")?;let c=self.calls.get(id).ok_or("Unexpected final function item")?;if item["call_id"]!=c.id||item["name"]!=c.name||item["arguments"]!=c.arguments{return Err("Final function differs from staged call".into())}}self.output=output.clone();}self.completed=true;},
 "response.failed"|"response.incomplete"|"error"=>{self.failure=Some("Provider response did not complete".into());},_=>{}}
 if self.text.len()>4*1024*1024||self.calls.len()>128{return Err("Response exceeds staging bounds".into())}Ok(())}
 pub fn finish(self)->Result<(String,Vec<FunctionCall>),String>{let(text,calls,_)=self.finish_with_items()?;Ok((text,calls))}
 pub fn finish_with_items(mut self)->Result<(String,Vec<FunctionCall>,Vec<Value>),String>{if let Some(e)=self.failure{return Err(e)}if !self.completed{return Err("Response ended before completed".into())}let mut ids=std::collections::HashSet::new();for c in self.calls.values(){if !ids.insert(c.id.clone()){return Err("Duplicate function call id".into())}if !c.done||c.id.is_empty()||c.name.is_empty()||!serde_json::from_str::<Value>(&c.arguments).map(|x|x.is_object()).unwrap_or(false){return Err("Incomplete or invalid function call".into())}}Ok((self.text,self.order.into_iter().map(|id|self.calls.remove(&id).unwrap()).collect(),self.output))}
}
#[cfg(test)]mod tests{use super::*;use serde_json::json;#[test]fn partial_never_executes(){let mut s=ResponseStage::default();s.push(&json!({"type":"response.output_item.added","item":{"type":"function_call","id":"i","call_id":"c","name":"write_slide"}})).unwrap();assert!(s.finish().is_err());}#[test]fn completed_function_only(){let mut s=ResponseStage::default();for v in [json!({"type":"response.output_item.added","item":{"type":"function_call","id":"i","call_id":"c","name":"read_deck"}}),json!({"type":"response.function_call_arguments.delta","item_id":"i","delta":"{}"}),json!({"type":"response.function_call_arguments.done","item_id":"i","arguments":"{}"}),json!({"type":"response.completed","response":{"status":"completed"}})]{s.push(&v).unwrap()}assert_eq!(s.finish().unwrap().1[0].name,"read_deck");}#[test]fn incomplete_is_not_success(){let mut s=ResponseStage::default();s.push(&json!({"type":"response.incomplete"})).unwrap();assert!(s.finish().is_err());}#[test]fn unknown_item_rejected(){assert!(ResponseStage::default().push(&json!({"type":"response.function_call_arguments.delta","item_id":"unknown","delta":"{}"})).is_err());}}

/// Convert the existing reviewed Chat history into explicit Responses items.
/// Unsupported content fails closed rather than silently dropping images/tools.
pub fn request_from_chat(model:&str,messages:&[Value],tools:&[Value])->Result<Value,String>{
 let mut input=Vec::new();
 for m in messages{if let Some(items)=m.get("responses_output").and_then(|x|x.as_array()){input.extend(items.iter().cloned());continue}let role=m["role"].as_str().ok_or("Missing message role")?;
 if role=="tool"{let id=m["tool_call_id"].as_str().filter(|x|!x.is_empty()).ok_or("Missing tool result call id")?;input.push(serde_json::json!({"type":"function_call_output","call_id":id,"output":m["content"].as_str().ok_or("Tool output must be text")?}));continue}
 if !matches!(role,"system"|"developer"|"user"|"assistant"){return Err("Unsupported message role".into())}
 let mut content=Vec::new();match &m["content"]{
 Value::String(text)=>{if !text.is_empty(){content.push(serde_json::json!({"type":if role=="assistant"{"output_text"}else{"input_text"},"text":text}));}},
 Value::Array(parts)=>for part in parts{match part["type"].as_str(){Some("text")=>content.push(serde_json::json!({"type":if role=="assistant"{"output_text"}else{"input_text"},"text":part["text"].as_str().ok_or("Missing text")?})),Some("image_url") if role=="user"=>content.push(serde_json::json!({"type":"input_image","image_url":part["image_url"]["url"].as_str().ok_or("Missing image URL")?})),_=>return Err("Unsupported Responses content part".into())}},Value::Null=>{},_=>return Err("Unsupported message content".into())}
 if !content.is_empty(){input.push(serde_json::json!({"role":role,"content":content}));}
 if let Some(calls)=m["tool_calls"].as_array(){for c in calls{let f=&c["function"];let arguments=f["arguments"].as_str().ok_or("Missing function arguments")?;let _:Value=serde_json::from_str(arguments).map_err(|_|"Invalid historical function arguments")?;input.push(serde_json::json!({"type":"function_call","call_id":c["id"].as_str().ok_or("Missing function call id")?,"name":f["name"].as_str().ok_or("Missing function name")?,"arguments":arguments}));}}
 }
 let tools=tools.iter().map(|t|{let f=&t["function"];if t["type"]!="function"||!f["parameters"].is_object(){return Err("Unsupported tool definition".to_string())}Ok(serde_json::json!({"type":"function","name":f["name"].as_str().ok_or("Missing tool name")?,"description":f["description"],"parameters":f["parameters"],"strict":false}))}).collect::<Result<Vec<_>,String>>()?;
 Ok(serde_json::json!({"model":model,"input":input,"tools":tools,"store":false,"stream":true,"include":["reasoning.encrypted_content"]}))
}
#[cfg(test)]mod request_tests{use super::*;use serde_json::json;#[test]fn preserves_tool_pair_and_images(){let r=request_from_chat("m",&[json!({"role":"user","content":[{"type":"text","text":"review"},{"type":"image_url","image_url":{"url":"data:image/png;base64,AA=="}}]}),json!({"role":"assistant","content":"","tool_calls":[{"id":"c1","type":"function","function":{"name":"read_deck","arguments":"{}"}}]}),json!({"role":"tool","tool_call_id":"c1","content":"result"})],&[]).unwrap();assert_eq!(r["store"],false);assert_eq!(r["input"][0]["content"][1]["type"],"input_image");assert_eq!(r["input"][1]["call_id"],r["input"][2]["call_id"]);}#[test]fn unsupported_part_is_not_silently_lost(){assert!(request_from_chat("m",&[json!({"role":"user","content":[{"type":"video","url":"x"}]})],&[]).is_err());}#[test]fn tool_definition_conversion(){let r=request_from_chat("m",&[],&[json!({"type":"function","function":{"name":"read_deck","description":"read","parameters":{"type":"object","properties":{}}}})]).unwrap();assert_eq!(r["tools"][0]["name"],"read_deck");assert_eq!(r["tools"][0]["strict"],false);}}

/// Decode byte-fragmented SSE with bounded buffering. Any decode/event error
/// poisons the decoder, so callers cannot release staged calls after an error.
#[derive(Default)]pub struct ResponseSse{bytes:Vec<u8>,stage:ResponseStage,failed:bool}
impl ResponseSse{
 pub fn push_bytes(&mut self,bytes:&[u8])->Result<(),String>{let result=self.decode(bytes);if result.is_err(){self.failed=true;}result}
 fn decode(&mut self,bytes:&[u8])->Result<(),String>{if self.failed{return Err("Response decoder already failed".into())}self.bytes.extend_from_slice(bytes);if self.bytes.len()>4*1024*1024{return Err("SSE frame exceeds bound".into())}loop{let boundary=[self.bytes.windows(2).position(|w|w==b"\n\n").map(|i|(i,2)),self.bytes.windows(4).position(|w|w==b"\r\n\r\n").map(|i|(i,4))].into_iter().flatten().min_by_key(|x|x.0);let Some((i,len))=boundary else{break};let frame=self.bytes.drain(..i+len).collect::<Vec<_>>();let text=std::str::from_utf8(&frame).map_err(|_|"Invalid UTF-8 SSE")?;let data=text.lines().filter_map(|l|l.strip_prefix("data:").map(str::trim_start)).collect::<Vec<_>>().join("\n");if data.is_empty(){continue}let value=serde_json::from_str::<Value>(&data).map_err(|_|"Invalid Responses SSE JSON")?;self.stage.push(&value)?;}Ok(())}
 pub fn finish(self)->Result<(String,Vec<FunctionCall>),String>{let(text,calls,_)=self.finish_with_items()?;Ok((text,calls))}
 pub fn finish_with_items(self)->Result<(String,Vec<FunctionCall>,Vec<Value>),String>{if self.failed||self.bytes.iter().any(|b|!b.is_ascii_whitespace()){return Err("Invalid or truncated Responses stream".into())}self.stage.finish_with_items()}
}
#[cfg(test)]mod sse_tests{use super::*;#[test]fn arbitrary_utf8_fragmentation_and_crlf(){let wire="data: {\"type\":\"response.output_text.delta\",\"delta\":\"héllo\"}\r\n\r\ndata: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\"}}\r\n\r\n";let mut s=ResponseSse::default();for b in wire.as_bytes(){s.push_bytes(&[*b]).unwrap()}assert_eq!(s.finish().unwrap().0,"héllo");}#[test]fn malformed_stream_poisoned(){let mut s=ResponseSse::default();assert!(s.push_bytes(b"data: broken\n\n").is_err());assert!(s.finish().is_err());}#[test]fn tail_cannot_be_ignored(){let mut s=ResponseSse::default();s.push_bytes(b"data: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\"}}\n\ndata: {").unwrap();assert!(s.finish().is_err());}}

/// Isolated transport seam, not selected by production settings yet.
/// Credentials stay in the caller, never returned in errors.
pub async fn receive_response(client:&reqwest::Client,url:&str,token:&str,request:&Value,cancel:&std::sync::atomic::AtomicBool,limit:std::time::Duration)->Result<(String,Vec<FunctionCall>),String>{let(text,calls,_)=receive_response_with_items(client,url,token,request,cancel,limit).await?;Ok((text,calls))}
pub async fn receive_response_with_items(client:&reqwest::Client,url:&str,token:&str,request:&Value,cancel:&std::sync::atomic::AtomicBool,limit:std::time::Duration)->Result<(String,Vec<FunctionCall>,Vec<Value>),String>{
 use futures_util::StreamExt;use std::sync::atomic::Ordering;use std::time::Duration;
 if cancel.load(Ordering::Relaxed){return Err("Cancelled before request".into())}
 let work=async{let response=client.post(url).bearer_auth(token).json(request).send().await.map_err(|_|"Responses connection failed")?;if !response.status().is_success(){return Err(format!("Responses HTTP {}",response.status().as_u16()))}let mut stream=response.bytes_stream();let mut decoder=ResponseSse::default();while let Some(chunk)=stream.next().await{let chunk=chunk.map_err(|_|"Responses stream interrupted")?;decoder.push_bytes(&chunk)?;}decoder.finish_with_items()};tokio::pin!(work);
 let deadline=tokio::time::sleep(limit);tokio::pin!(deadline);
 loop{tokio::select!{result=&mut work=>return result,_=&mut deadline=>return Err("Responses request deadline reached; no partial tools released".into()),_=tokio::time::sleep(Duration::from_millis(25))=>if cancel.load(Ordering::Relaxed){return Err("Responses cancelled; no partial tools released".into())}}}
}
#[cfg(test)]mod transport_tests{use super::*;use std::{io::{Read,Write},net::TcpListener,sync::atomic::AtomicBool,time::Duration};
 fn server(status:&str,body:&str)->String{let listener=TcpListener::bind("127.0.0.1:0").unwrap();let addr=listener.local_addr().unwrap();let status=status.to_string();let body=body.to_string();std::thread::spawn(move||{let(mut s,_)=listener.accept().unwrap();let mut b=[0u8;8192];let _=s.read(&mut b);let _=write!(s,"HTTP/1.1 {status}\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len());});format!("http://{addr}/responses")}
 #[tokio::test]async fn actual_http_completed_text(){let url=server("200 OK","data: {\"type\":\"response.output_text.delta\",\"delta\":\"fixture\"}\n\ndata: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\"}}\n\n");let r=receive_response(&reqwest::Client::new(),&url,"local-fake",&serde_json::json!({}),&AtomicBool::new(false),Duration::from_secs(3)).await.unwrap();assert_eq!(r.0,"fixture");}
 #[tokio::test]async fn actual_http_error_redacts_body(){let url=server("401 Unauthorized","secret-body-never-surface");let r=receive_response(&reqwest::Client::new(),&url,"local-fake",&serde_json::json!({}),&AtomicBool::new(false),Duration::from_secs(3)).await.unwrap_err();assert!(r.contains("401"));assert!(!r.contains("secret"));}
 #[tokio::test]async fn cancelled_before_connection(){let r=receive_response(&reqwest::Client::new(),"http://127.0.0.1:1/responses","local-fake",&serde_json::json!({}),&AtomicBool::new(true),Duration::from_secs(1)).await;assert!(r.unwrap_err().contains("Cancelled"));}
 #[tokio::test]async fn incomplete_http_cannot_commit(){let url=server("200 OK","data: {\"type\":\"response.output_text.delta\",\"delta\":\"partial\"}\n\n");assert!(receive_response(&reqwest::Client::new(),&url,"local-fake",&serde_json::json!({}),&AtomicBool::new(false),Duration::from_secs(3)).await.is_err());}
}
#[cfg(test)]mod timeout_tests{use super::*;use std::{io::Read,net::TcpListener,sync::atomic::{AtomicBool,Ordering},time::Duration};#[tokio::test]async fn deadline_before_headers(){let listener=TcpListener::bind("127.0.0.1:0").unwrap();let url=format!("http://{}/responses",listener.local_addr().unwrap());let h=std::thread::spawn(move||{let(mut s,_)=listener.accept().unwrap();let mut b=[0;4096];let _=s.read(&mut b);std::thread::sleep(Duration::from_millis(150));});let e=receive_response(&reqwest::Client::new(),&url,"fake",&serde_json::json!({}),&AtomicBool::new(false),Duration::from_millis(40)).await.unwrap_err();assert!(e.contains("deadline"));h.join().unwrap();}#[tokio::test]async fn cancel_before_headers(){let listener=TcpListener::bind("127.0.0.1:0").unwrap();let url=format!("http://{}/responses",listener.local_addr().unwrap());let h=std::thread::spawn(move||{let(mut s,_)=listener.accept().unwrap();let mut b=[0;4096];let _=s.read(&mut b);std::thread::sleep(Duration::from_millis(150));});let cancel=AtomicBool::new(false);let c=async{tokio::time::sleep(Duration::from_millis(30)).await;cancel.store(true,Ordering::Relaxed);};let client=reqwest::Client::new();let request=serde_json::json!({});let work=receive_response(&client,&url,"fake",&request,&cancel,Duration::from_secs(2));let(r,_)=tokio::join!(work,c);assert!(r.unwrap_err().contains("cancelled"));h.join().unwrap();}}
#[cfg(test)]mod continuity_tests{use super::*;use serde_json::json;#[test]fn opaque_reasoning_and_phase_replayed_without_duplication(){let output=vec![json!({"type":"reasoning","id":"r1","encrypted_content":"opaque-fixture","summary":[]}),json!({"type":"message","id":"m1","role":"assistant","phase":"commentary","content":[{"type":"output_text","text":"checking"}]})];let mut stage=ResponseStage::default();stage.push(&json!({"type":"response.completed","response":{"status":"completed","output":output}})).unwrap();let(_,_,items)=stage.finish_with_items().unwrap();let request=request_from_chat("model",&[json!({"role":"assistant","content":"checking","responses_output":items}),json!({"role":"user","content":"continue"})],&[]).unwrap();assert_eq!(request["input"][0]["encrypted_content"],"opaque-fixture");assert_eq!(request["input"][1]["phase"],"commentary");assert_eq!(request["input"].as_array().unwrap().len(),3);}#[test]fn unsupported_hosted_output_blocks_instead_of_dropping(){let mut s=ResponseStage::default();assert!(s.push(&json!({"type":"response.completed","response":{"status":"completed","output":[{"type":"computer_call"}]}})).is_err());}}

/// A credential/model/endpoint change must never reuse another account's output.
pub fn continuity_scope(settings:&crate::model::AppSettings)->String{use sha2::{Digest,Sha256};let raw=serde_json::json!([settings.active_connection,settings.provider_kind,settings.base_url.trim_end_matches('/'),settings.model,settings.api_key]);format!("{:x}",Sha256::digest(raw.to_string().as_bytes()))}
#[cfg(test)]mod scope_tests{use super::*;#[test]fn credential_model_and_endpoint_changes_isolate(){let mut s=crate::model::AppSettings::default();let a=continuity_scope(&s);s.api_key="secret-different-account".into();let b=continuity_scope(&s);assert_ne!(a,b);assert!(!b.contains("secret"));s.model="other".into();assert_ne!(b,continuity_scope(&s));}}
#[cfg(test)]mod final_consistency_tests{use super::*;use serde_json::json;#[test]fn final_payload_cannot_replace_staged_function(){let mut s=ResponseStage::default();s.push(&json!({"type":"response.output_item.added","item":{"type":"function_call","id":"i","call_id":"c","name":"read_deck"}})).unwrap();s.push(&json!({"type":"response.function_call_arguments.done","item_id":"i","arguments":"{}"})).unwrap();assert!(s.push(&json!({"type":"response.completed","response":{"status":"completed","output":[{"type":"function_call","id":"i","call_id":"c","name":"write_slide","arguments":"{}"}]}})).is_err());}#[test]fn mixed_sse_newlines_preserve_order(){let mut d=ResponseSse::default();d.push_bytes(b"data: {\"type\":\"response.output_text.delta\",\"delta\":\"one\"}\r\n\r\ndata: {\"type\":\"response.completed\",\"response\":{\"status\":\"completed\"}}\n\n").unwrap();assert_eq!(d.finish().unwrap().0,"one");}}
